import { test, expect } from '@playwright/test';

test.describe('File Upload - Maximum Size Limit', () => {
  let uploadPage: string;

  test.beforeEach(async ({ page }) => {
    uploadPage = 'data:text/html,<html><body><input type="file" id="fileInput" /><button id="uploadBtn">Upload</button><div id="errorMessage"></div></body></html>';
    await page.goto(uploadPage);
  });

  test('should display error message when file exceeds maximum size limit', async ({ page }) => {
    const maxFileSizeBytes = 5 * 1024 * 1024; // 5MB limit
    const oversizedFileSize = 10 * 1024 * 1024; // 10MB file

    // Create a mock oversized file
    const fileBuffer = Buffer.alloc(oversizedFileSize);

    // Set up file input handler
    await page.evaluate(() => {
      const fileInput = document.getElementById('fileInput') as HTMLInputElement;
      const uploadBtn = document.getElementById('uploadBtn') as HTMLButtonElement;
      const errorDiv = document.getElementById('errorMessage') as HTMLDivElement;

      const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

      uploadBtn.addEventListener('click', () => {
        if (fileInput.files && fileInput.files[0]) {
          const file = fileInput.files[0];
          if (file.size > MAX_FILE_SIZE) {
            errorDiv.textContent = `Error: File size exceeds maximum limit of 5MB. Your file is ${(file.size / 1024 / 1024).toFixed(2)}MB.`;
            errorDiv.style.color = 'red';
          } else {
            errorDiv.textContent = 'File uploaded successfully';
            errorDiv.style.color = 'green';
          }
        }
      });
    });

    // Upload oversized file
    const fileInput = await page.locator('input[type="file"]');
    await fileInput.setInputFiles({
      name: 'large-file.bin',
      mimeType: 'application/octet-stream',
      buffer: fileBuffer,
    });

    // Click upload button
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Verify error message is displayed
    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Error: File size exceeds maximum limit of 5MB');
    await expect(errorMessage).toHaveCSS('color', 'rgb(255, 0, 0)');
  });

